<?php
function icon(string $name): string {
    $paths=['grid'=>'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z','bag'=>'M5 7h14l1 14H4L5 7z M9 7V5a3 3 0 016 0v2','menu'=>'M4 5h16 M4 12h16 M4 19h16','bowl'=>'M3 11h18a9 9 0 01-18 0z M8 4v3 M12 3v4 M16 4v3','box'=>'M3 7l9-4 9 4-9 4-9-4z M3 7v10l9 4 9-4V7 M12 11v10','chart'=>'M4 3v17h17 M8 16v-5 M13 16V7 M18 16V4','users'=>'M16 21v-3a4 4 0 00-4-4H6a4 4 0 00-4 4v3 M9 3a4 4 0 110 8 4 4 0 010-8 M17 4a4 4 0 010 8 M22 21v-3a4 4 0 00-3-3.87','cash'=>'M3 6h18v12H3z M12 9a3 3 0 110 6 3 3 0 010-6 M6 12h.01 M18 12h.01','clock'=>'M12 3a9 9 0 110 18 9 9 0 010-18 M12 7v5l3 2','arrow'=>'M5 12h14 M13 6l6 6-6 6','leaf'=>'M20 3C8 2 2 8 5 15c3 7 15 3 15-12z M4 21L15 9','settings'=>'M12 8a4 4 0 110 8 4 4 0 010-8 M12 2v3 M12 19v3 M2 12h3 M19 12h3 M5 5l2 2 M17 17l2 2 M5 19l2-2 M17 7l2-2','receipt'=>'M5 3h14v18l-3-2-4 2-4-2-3 2V3z M8 7h8 M8 11h8 M8 15h4','search'=>'M10 3a7 7 0 110 14 7 7 0 010-14 M15 15l6 6','plus'=>'M12 5v14 M5 12h14','check'=>'M5 12l4 4L19 6','logout'=>'M9 3H4v18h5 M10 12h11 M17 8l4 4-4 4'];
    return '<svg viewBox="0 0 24 24" width="20" height="20" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="'.($paths[$name]??$paths['grid']).'"/></svg>';
}
function routeRoles(string $p): array {
    if(isset(masters()[$p]) || in_array($p,['combos','expenses','reports','audit','settings']))return ['Owner'];
    if(in_array($p,['pos','sales','sale','cash-session']))return ['Owner','Cashier'];
    if(in_array($p,['daily-menu','inventory','movements','receiving','receipt']))return ['Owner','Staff'];
    return ['Owner','Cashier','Staff'];
}
function pages(): array {return ['dashboard'=>'Overview','pos'=>'Counter POS','daily-menu'=>'Today’s menu','refills'=>'Rice refills','sales'=>'Sales history','sale'=>'Transaction details','cash-session'=>'Cash drawer','catalog'=>'Dish catalog','categories'=>'Menu categories','combos'=>'Combo builder','inventory'=>'Stock overview','ingredients'=>'Ingredient catalog','movements'=>'Stock movements','receiving'=>'Stock receiving','receipt'=>'Purchase details','suppliers'=>'Suppliers','units'=>'Units','expenses'=>'Operating expenses','expense-categories'=>'Expense categories','reports'=>'Reports','users'=>'Team accounts','audit'=>'Activity log','profile'=>'My profile','settings'=>'Workspace guide'];}
function field(string $label,string $name,string $type='text',mixed $value='',string $extra=''): void {echo '<label>'.h($label).'<input type="'.h($type).'" name="'.h($name).'" value="'.h($value).'" '.$extra.'></label>';}
function selectField(string $label,string $name,array $choices,mixed $value='',bool $optional=false): void {echo '<div class="field"><label for="field-'.h($name).'">'.h($label).'</label><select id="field-'.h($name).'" name="'.h($name).'" '.($optional?'':'required').'>';echo '<option value="">'.($optional?'None':'Choose…').'</option>';foreach($choices as $k=>$v)echo '<option value="'.h($k).'" '.((string)$k===(string)$value?'selected':'').'>'.h($v).'</option>';echo '</select></div>';}
function options(string $table,string $id,string $label,string $where='1=1'): array {return array_column(rows("SELECT `$id`,`$label` FROM `$table` WHERE $where ORDER BY `$label`"),$label,$id);}
function formStart(string $action,array $hidden=[],string $class='form-grid'): void {echo '<form method="post" class="'.h($class).'"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="action" value="'.h($action).'">';foreach($hidden as $k=>$v)echo '<input type="hidden" name="'.h($k).'" value="'.h($v).'">';}
function formEnd(string $label='Save changes'): void {echo '<div class="form-actions full"><button class="btn primary">'.h($label).'</button></div></form>';}
function buttonForm(string $action,array $hidden,string $label,string $confirm='',string $style='ghost small'): string {ob_start();formStart($action,$hidden,'inline');echo '<button class="btn '.h($style).'" '.($confirm?'data-confirm="'.h($confirm).'"':'').'>'.h($label).'</button></form>';return ob_get_clean();}
function badge(string $label,string $kind=''): string {return '<span class="badge '.h($kind).'">'.h($label).'</span>';}
function emptyState(string $message): void {echo '<div class="empty">'.icon('bowl').'<h3>Nothing here just yet</h3><p>'.h($message).'</p></div>';}
function tableView(array $headers,array $data,string $empty='Your records will appear here.',bool $paginate=true): void {
    if(!$data){emptyState($empty);return;}
    $count=count($data);$page=max(1,min((int)($_GET['n']??1),(int)ceil($count/12)));if($paginate)$data=array_slice($data,($page-1)*12,12);
    echo '<div class="table-wrap"><table><thead><tr>';foreach($headers as $x)echo '<th>'.h($x).'</th>';echo '</tr></thead><tbody>';
    foreach($data as $r){echo '<tr>';foreach($r as $x)echo '<td>'.$x.'</td>';echo '</tr>';}echo '</tbody></table></div>';
    if($paginate&&$count>12){echo '<div class="pagination"><span>'.h($count).' records · Page '.$page.' of '.ceil($count/12).'</span><div>';foreach([[$page-1,'← Previous'],[$page+1,'Next →']]as [$p,$label])if($p>=1&&$p<=ceil($count/12)){echo '<a class="btn ghost small" href="?'.h(http_build_query([...$_GET,'n'=>$p])).'">'.$label.'</a>';}echo '</div></div>';}
}
function filterBar(string $placeholder='Search records…',bool $dates=false): void {echo '<form class="filters" method="get"><input type="hidden" name="page" value="'.h($_GET['page']??'dashboard').'"><div class="search-field">'.icon('search').'<input aria-label="Search" name="q" placeholder="'.h($placeholder).'" value="'.h($_GET['q']??'').'"></div>';if($dates){field('From','from','date',$_GET['from']??today());field('To','to','date',$_GET['to']??today());}echo '<button class="btn ghost">Apply</button><a class="reset" href="?page='.h($_GET['page']??'dashboard').'">Reset</a></form>';}
function matches(string $s): bool {$q=trim((string)($_GET['q']??''));return $q===''||mb_stripos($s,$q)!==false;}
function metric(string $label,string $value,string $hint,string $icon='chart'): void {echo '<article class="metric"><div class="metric-top"><span>'.h($label).'</span><span class="metric-icon">'.icon($icon).'</span></div><strong>'.h($value).'</strong><small>'.h($hint).'</small></article>';}
function layoutStart(string $page): void {
    $u=need();$role=$u['role_name'];$title=pages()[$page]??'Workspace';
    ?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#173e32"><title><?=h($title)?> · CarinderEase</title><link rel="stylesheet" href="assets/app.css"><script src="assets/app.js" defer></script></head><body><aside class="sidebar" id="sidebar"><a class="brand" href="index.php"><span class="brand-mark">C<span>✦</span></span><span>Carinder<span>Ease</span></span></a><div class="workspace-chip"><span class="status-dot"></span> My carinderia <span class="tiny">LOCAL</span></div><nav aria-label="Main navigation"><?php
    $groups=['YOUR DAY'=>[['dashboard','grid'],['pos','bag'],['daily-menu','bowl'],['refills','leaf'],['sales','receipt'],['cash-session','cash']], 'MENU & KITCHEN'=>[['catalog','bowl'],['categories','grid'],['combos','plus'],['inventory','box'],['ingredients','leaf'],['movements','clock'],['receiving','box'],['suppliers','users'],['units','settings']], 'BUSINESS'=>[['expenses','cash'],['expense-categories','grid'],['reports','chart'],['users','users'],['audit','clock'],['settings','settings']]];
    foreach($groups as $group=>$links){$visible=array_filter($links,fn($l)=>in_array($role,routeRoles($l[0])));if(!$visible)continue;echo '<div class="nav-label">'.$group.'</div>';foreach($visible as [$p,$i])echo '<a href="?page='.$p.'" class="nav-link '.($page===$p?'active':'').'">'.icon($i).'<span>'.h(pages()[$p]).'</span>'.($p==='pos'?'<span class="nav-tag">POS</span>':'').'</a>';}
    ?></nav><div class="sidebar-bottom"><div class="little-sun">✦</div><strong>A little easier, every day.</strong><p>Made for your neighborhood kitchen.</p></div></aside><div class="main-shell"><header class="topbar"><div class="crumb"><button class="icon-btn" id="menu-toggle" aria-label="Toggle navigation"><?=icon('menu')?></button><span>Workspace</span><b>/</b><strong><?=h($title)?></strong></div><div class="top-right"><span class="date-chip"><?=h(date('D, M j'))?></span><a href="?page=profile" class="user-chip"><span class="avatar"><?=h(mb_strtoupper(mb_substr($u['full_name'],0,1)))?></span><span><?=h($u['full_name'])?><small><?=h($role==='Owner'?'Owner / Admin':$role)?></small></span></a><?=buttonForm('logout',[],'Sign out','','ghost small')?></div></header><main class="content"><?php
    if(!empty($_SESSION['flash'])){$f=$_SESSION['flash'];unset($_SESSION['flash']);echo '<div role="status" class="notice '.h($f['type']).'">'.h($f['text']).'</div>';}
    if(!empty($GLOBALS['page_error']))echo '<div role="alert" class="notice error">'.h($GLOBALS['page_error']).'</div>';
}
function layoutEnd(): void {echo '</main><footer class="page-footer"><span>CarinderEase · Made for the everyday.</span><span>Single branch · Asia/Manila</span></footer></div><div id="toast" role="status"></div></body></html>';}
function heading(string $eyebrow,string $title,string $description,string $action=''): void {echo '<div class="page-heading"><div><div class="eyebrow">'.h($eyebrow).'</div><h1>'.h($title).'</h1><p>'.h($description).'</p></div>'.$action.'</div>';}
function foodEmoji(string $name): string {
    $asset='combo';
    foreach(['combo'=>'combo','meal'=>'combo','rice'=>'rice','tilapia'=>'fish','fish'=>'fish','tea'=>'tea','water'=>'water','monggo'=>'beans','pinakbet'=>'vegetables','chicken'=>'chicken','afritada'=>'chicken','sinigang'=>'soup','adobo'=>'adobo','bicol'=>'spicy'] as $word=>$file)if(stripos($name,$word)!==false){$asset=$file;break;}
    return '<img class="food-icon" src="assets/food/'.$asset.'.svg" alt="" width="180" height="140">';
}
